With functions, pipelines, objects, and control structures under our belts, we
can turn to one of the more basic ideas in many programming languages:
variables. In templates, they are less frequently used. But we will see how to
use them to simplify code, and to make better use of with and range.

In an earlier example, we saw that this code will fail:

{{- with .Values.favorite }}
drink: {{ .drink | default "tea" | quote }}
food: {{ .food | upper | quote }}
release: {{ .Release.Name }}
{{- end }}

Release.Name is not inside of the scope that's restricted in the with block.
One way to work around scoping issues is to assign objects to variables that can
be accessed without respect to the present scope.

In Helm templates, a variable is a named reference to another object. It follows
the form $name. Variables are assigned with a special assignment operator:
:=. We can rewrite the above to use a variable for Release.Name.

apiVersion: v1
kind: ConfigMap
metadata:
name: {{ .Release.Name }}-configmap
data:
myvalue: "Hello World"
{{- $relname := .Release.Name -}}
{{- with .Values.favorite }}
drink: {{ .drink | default "tea" | quote }}
food: {{ .food | upper | quote }}
release: {{ $relname }}
{{- end }}

Notice that before we start the with block, we assign $relname :=
.Release.Name. Now inside of the with block, the $relname variable still
points to the release name.

Running that will produce this:

-h, --help help for all
--revision int get the named release with revision
--template string go template for formatting the output, eg: {{.Release.Name}}

package main

import (
"context"
"fmt"
"log"

"helm.sh/helm/v3/pkg/action"
"helm.sh/helm/v3/pkg/chart/loader"
"helm.sh/helm/v3/pkg/cli"
"helm.sh/helm/v3/pkg/downloader"
"helm.sh/helm/v3/pkg/getter"
)

func runInstall(ctx context.Context, logger *log.Logger, settings *cli.EnvSettings, releaseName string, chartRef string, chartVersion string, releaseValues map[string]interface{}) error {

actionConfig, err := initActionConfig(settings, logger)
if err != nil {
return fmt.Errorf("failed to init action config: %w", err)
}

installClient := action.NewInstall(actionConfig)

installClient.DryRunOption = "none"
installClient.ReleaseName = releaseName
installClient.Namespace = settings.Namespace()
installClient.Version = chartVersion

registryClient, err := newRegistryClientTLS(
settings,
logger,
installClient.CertFile,
installClient.KeyFile,
installClient.CaFile,
installClient.InsecureSkipTLSverify,
installClient.PlainHTTP)
if err != nil {
return fmt.Errorf("failed to created registry client: %w", err)
}
installClient.SetRegistryClient(registryClient)

chartPath, err := installClient.ChartPathOptions.LocateChart(chartRef, settings)
if err != nil {
return err
}

providers := getter.All(settings)

chart, err := loader.Load(chartPath)
if err != nil {
return err
}

// Check chart dependencies to make sure all are present in /charts
if chartDependencies := chart.Metadata.Dependencies; chartDependencies != nil {
if err := action.CheckDependencies(chart, chartDependencies); err != nil {
err = fmt.Errorf("failed to check chart dependencies: %w", err)
if !installClient.DependencyUpdate {
return err
}

manager := &downloader.Manager{
Out: logger.Writer(),
ChartPath: chartPath,
Keyring: installClient.ChartPathOptions.Keyring,
SkipUpdate: false,
Getters: providers,
RepositoryConfig: settings.RepositoryConfig,
RepositoryCache: settings.RepositoryCache,
Debug: settings.Debug,
RegistryClient: installClient.GetRegistryClient(),
}
if err := manager.Update(); err != nil {
return err
}
// Reload the chart with the updated Chart.lock file.
if chart, err = loader.Load(chartPath); err != nil {
return fmt.Errorf("failed to reload chart after repo update: %w", err)
}
}
}

release, err := installClient.RunWithContext(ctx, chart, releaseValues)
if err != nil {
return fmt.Errorf("failed to run install: %w", err)
}

logger.Printf("release created:\n%+v", *release)

return nil
}

